import importlib.util
import importlib.metadata
from unittest.mock import patch
from xarray.namedarray.utils import module_available

def test_module_available_none_version():
    with patch("importlib.util.find_spec") as mock_find_spec, \
         patch("importlib.metadata.version") as mock_version:
        mock_find_spec.return_value = True # Module found
        mock_version.return_value = None   # Version not found

        try:
            result = module_available("some_module", minversion="1.0.0")
            if result is False:
                print("Success: returned False")
                return True
            else:
                print(f"Failure: returned {result}")
                return False
        except TypeError:
            print("Failure: raised TypeError")
            return False
        except Exception as e:
            print(f"Failure: raised {type(e).__name__}: {e}")
            return False

if __name__ == "__main__":
    if test_module_available_none_version():
        exit(0)
    else:
        exit(1)

